#include <iostream>
#include <sstream>
#include <stdexcept>

struct Token {
    char clase;
    int valor;
};

Token leer_token(std::istringstream& entrada) {
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') {
            continue;
        }
        if (actual >= '0' && actual <= '9') {
            int valor = actual - '0';
            while (entrada.get(actual)) {
                if (actual >= '0' && actual <= '9') {
                    valor = valor * 10 + (actual - '0');
                    if (valor > 99) {
                        throw std::runtime_error("Number out of range");
                    }
                } else {
                    entrada.putback(actual);
                    if (!entrada) {
                        throw std::runtime_error("Could not put back character");
                    }
                    return Token{'n', valor};
                }
            }
            if (entrada.bad() || !entrada.eof()) {
                throw std::runtime_error("Stream failure");
            }
            return Token{'n', valor};
        }
        if (actual == '+' || actual == '-' || actual == '*'
                || actual == '/' || actual == '(' || actual == ')'
                || actual == ';') {
            return Token{actual, 0};
        }
        throw std::runtime_error("Unsupported character");
    }
    if (entrada.bad() || !entrada.eof()) {
        throw std::runtime_error("Stream failure");
    }
    return Token{'f', 0};
}

int main() {
    std::istringstream entrada{"27+4;"};
    try {
        const Token numero = leer_token(entrada);
        const Token signo = leer_token(entrada);
        std::cout << numero.clase << ":" << numero.valor << "\n";
        std::cout << signo.clase;
    } catch (const std::runtime_error& error) {
        std::cout << "Error: " << error.what();
    }
    return 0;
}

